import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {int MAX = 1000001;int[] divisorCount = new int[MAX];for (int i = 1; i < MAX; i++) {for (int j = i; j < MAX; j += i) {divisorCount[j]++;}}BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line1 = br.readLine();if (line1 == null) return;int n = Integer.parseInt(line1.trim());long[] freq = new long[MAX];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {int val = Integer.parseInt(st.nextToken());int count = divisorCount[val];freq[count]++;}long totalPairs = 0;for (int i = 0; i < MAX; i++) {if (freq[i] > 1) {totalPairs += (freq[i] * (freq[i] - 1)) / 2;}}System.out.println(totalPairs);}}